        })
            .useMocker(createMock)
            .compile();
        controller = module.get<PrivateAPIUsageController>(PrivateAPIUsageController);
    });

    it('stores under source file, twice without overwrite', async () => {
        const s3Key = `biz-test/2026/01/01/usage-${Math.random().toString(36).slice(2, 8)}.json`;
        for (const i of [1, 2]) {
            await expect(controller.dbUsage({ message: '{bad json', s3Key })).rejects.toThrow(/Invalid message format/);
