        expect(list.Contents.length).toBe(2);
        const doc = await s3.send(new GetObjectCommand({ Bucket: BUCKET, Key: list.Contents[0].Key }));
        const body = JSON.parse(await doc.Body.transformToString());
        console.log(JSON.stringify(body, null, 1));
